import { UsageError } from './errors.js'

const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/** Splits the input into lines, dropping the empty tail a trailing newline leaves. */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parses the input text into a graph.
 *
 * The result holds `tasks`, a map from name to `{ name, cost, deps }` where
 * `deps` is an array of dependency names in the order they were first seen.
 */
export function parseGraph(text) {
  const tasks = new Map()
  const pending = [] // dep lines, resolved once every task line has been read
  const lines = splitLines(text)

  for (let i = 0; i < lines.length; i += 1) {
    const number = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw new UsageError(`line ${number}: expected task <name> <cost>`)
      const [, name, cost] = words
      if (!NAME.test(name)) throw new UsageError(`line ${number}: invalid task name ${name}`)
      if (!COST.test(cost)) throw new UsageError(`line ${number}: cost must be a non-negative integer`)
      if (tasks.has(name)) throw new UsageError(`line ${number}: task ${name} is declared twice`)
      tasks.set(name, { name, cost: Number(cost), deps: [], depSet: new Set() })
      continue
    }

    if (directive === 'dep') {
      if (words.length < 3) throw new UsageError(`line ${number}: expected dep <name> <dependency>...`)
      for (let w = 1; w < words.length; w += 1) {
        if (!NAME.test(words[w])) throw new UsageError(`line ${number}: invalid task name ${words[w]}`)
      }
      pending.push(words.slice(1))
      continue
    }

    throw new UsageError(`line ${number}: unknown directive ${directive}`)
  }

  for (const names of pending) {
    for (const name of names) {
      if (!tasks.has(name)) throw new UsageError(`unknown task ${name}`)
    }
  }

  for (const names of pending) {
    const task = tasks.get(names[0])
    for (let w = 1; w < names.length; w += 1) {
      const dependency = names[w]
      if (task.depSet.has(dependency)) continue
      task.depSet.add(dependency)
      task.deps.push(dependency)
    }
  }

  return { tasks }
}

/** The task names in ascending order. */
export function sortedNames(graph) {
  return [...graph.tasks.keys()].sort(compareNames)
}

/** Ascending name order, by code unit. */
export function compareNames(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}
"}

