{"file_path":"src/graph.js","content":"/** Deriving depths, times and priorities from a parsed graph. */

import { CycleError } from './errors.js'
import { compareNames, sortedNames } from './parse.js'

/**
 * Finds the first cycle a depth first search meets, starting from each task in
 * ascending name order and walking each task's dependencies in ascending name
 * order. Throws a CycleError, or returns when the graph is acyclic.
 */
export function checkAcyclic(graph) {
  const state = new Map() // name -> 'open' | 'done'
  const stack = []
  const names = sortedNames(graph)

  const visit = (name) => {
    state.set(name, 'open')
    stack.push(name)
    for (const dependency of orderedDeps(graph, name)) {
      const seen = state.get(dependency)
      if (seen === 'open') {
        const start = stack.indexOf(dependency)
        throw new CycleError([...stack.slice(start), dependency])
      }
      if (seen === undefined) visit(dependency)
    }
    stack.pop()
    state.set(name, 'done')
  }

  for (const name of names) {
    if (state.get(name) === undefined) visit(name)
  }
}

/** A task's dependencies in ascending name order. */
export function orderedDeps(graph, name) {
  return [...graph.tasks.get(name).deps].sort(compareNames)
}

/**
 * The schedule with unlimited workers: for every task its `start`, `finish`
 * and `depth`, plus the makespan `total`.
 */
export function analyse(graph) {
  const info = new Map()

  const resolve = (name) => {
    const known = info.get(name)
    if (known !== undefined) return known
    const task = graph.tasks.get(name)
    let start = 0
    let depth = 0
    for (const dependency of task.deps) {
      const parent = resolve(dependency)
      if (parent.finish > start) start = parent.finish
      if (parent.depth + 1 > depth) depth = parent.depth + 1
    }
    const entry = { name, start, finish: start + task.cost, depth }
    info.set(name, entry)
    return entry
  }

  let total = 0
  for (const name of sortedNames(graph)) {
    const entry = resolve(name)
    if (entry.finish > total) total = entry.finish
  }
  return { info, total }
}

/**
 * Each task's priority: the cost of the longest chain that begins at it,
 * counting its own cost and the costs down to a task nothing depends on.
 */
export function priorities(graph) {
  const dependents = new Map()
  for (const name of graph.tasks.keys()) dependents.set(name, [])
  for (const task of graph.tasks.values()) {
    for (const dependency of task.deps) dependents.get(dependency).push(task.name)
  }

  const priority = new Map()
  const resolve = (name) => {
    const known = priority.get(name)
    if (known !== undefined) return known
    let below = 0
    for (const child of dependents.get(name)) {
      const value = resolve(child)
      if (value > below) below = value
    }
    const total = graph.tasks.get(name).cost + below
    priority.set(name, total)
    return total
  }

  for (const name of graph.tasks.keys()) resolve(name)
  return priority
}
"}

