{"file_path":"src/schedule.js","content":"/** The bounded worker simulation behind `pack`. */

import { compareNames, sortedNames } from './parse.js'
import { priorities } from './graph.js'

/**
 * Runs the graph on `workerCount` workers, greedily starting the ready task of
 * greatest priority (ties by ascending name) on the free worker of smallest
 * index. Returns the run of every worker and the makespan.
 */
export function pack(graph, workerCount) {
  const priority = priorities(graph)
  const names = sortedNames(graph)
  const runs = []
  const free = [] // the instant each worker next becomes free
  for (let i = 0; i < workerCount; i += 1) {
    runs.push([])
    free.push(0)
  }

  const finish = new Map()
  const remaining = new Set(names)
  let time = 0
  let makespan = 0

  while (remaining.size > 0) {
    for (;;) {
      const worker = free.findIndex((when) => when <= time)
      if (worker === -1) break
      const choice = pickReady(graph, remaining, finish, priority, time)
      if (choice === null) break
      const end = time + graph.tasks.get(choice).cost
      runs[worker].push({ name: choice, start: time, finish: end })
      free[worker] = end
      finish.set(choice, end)
      remaining.delete(choice)
      if (end > makespan) makespan = end
    }

    let next = null
    for (const when of free) {
      if (when > time && (next === null || when < next)) next = when
    }
    if (next === null) break
    time = next
  }

  return { runs, makespan }
}

function pickReady(graph, remaining, finish, priority, time) {
  let best = null
  for (const name of remaining) {
    if (!isReady(graph, name, finish, time)) continue
    if (best === null) {
      best = name
      continue
    }
    const better =
      priority.get(name) > priority.get(best) ||
      (priority.get(name) === priority.get(best) && compareNames(name, best) < 0)
    if (better) best = name
  }
  return best
}

function isReady(graph, name, finish, time) {
  for (const dependency of graph.tasks.get(name).deps) {
    const done = finish.get(dependency)
    if (done === undefined || done > time) return false
  }
  return true
}
"}

