{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { UsageError } from './errors.js'
import { parseGraph, sortedNames } from './parse.js'
import { analyse, checkAcyclic } from './graph.js'
import { pack } from './schedule.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'

/** Reads the mode and worker count out of the command line arguments. */
export function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw new UsageError('workers must be a positive integer')
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new UsageError(USAGE)
}

/** Reads the whole of standard input as text. */
function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** Renders the report for the given arguments and input, as a single string. */
export function render(argv, text) {
  const options = parseArgs(argv)
  const graph = parseGraph(text)
  checkAcyclic(graph)

  if (options.mode === 'pack') {
    const { runs, makespan } = pack(graph, options.workers)
    const lines = runs.map((run, index) => {
      const entries = run.map((item) => ` ${item.name}@${item.start}-${item.finish}`).join('')
      return `worker ${index}:${entries}`
    })
    lines.push(`makespan ${makespan}`)
    return `${lines.join('\n')}\n`
  }

  const { info, total } = analyse(graph)
  const names = sortedNames(graph)
  const lines = []

  if (options.mode === 'explain') {
    for (const name of names) {
      const entry = info.get(name)
      lines.push(`${name} start=${entry.start} finish=${entry.finish} depth=${entry.depth}`)
    }
  } else {
    const waves = []
    for (const name of names) {
      const depth = info.get(name).depth
      if (waves[depth] === undefined) waves[depth] = []
      waves[depth].push(name)
    }
    for (let k = 0; k < waves.length; k += 1) {
      lines.push(`wave ${k}: ${(waves[k] ?? []).join(' ')}`)
    }
  }

  lines.push(`total ${total}`)
  return `${lines.join('\n')}\n`
}

function main() {
  let output
  try {
    output = render(process.argv.slice(2), readStdin())
  } catch (error) {
    if (error instanceof Error && typeof error.exitCode === 'number') {
      process.stderr.write(`error: ${error.message}\n`)
      process.exit(error.exitCode)
    }
    throw error
  }
  process.stdout.write(output)
}

main()
"}

