import { CycleError } from './errors.js'
import { compareNames, sortedNames } from './parse.js'

/**
 * Finds the first cycle a depth first search meets, starting from each task in
 * ascending name order and walking each task's dependencies in ascending name
 * order. Throws a CycleError, or returns when the graph is acyclic.
 *
 * The walk keeps its own stack so that a long chain cannot exhaust the call
 * stack.
 */
export function checkAcyclic(graph) {
  const state = new Map() // name -> 'open' | 'done'
  const names = sortedNames(graph)

  for (const root of names) {
    if (state.has(root)) continue
    const path = [root]
    const frames = [{ name: root, deps: orderedDeps(graph, root), index: 0 }]
    state.set(root, 'open')

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.index === frame.deps.length) {
        state.set(frame.name, 'done')
        frames.pop()
        path.pop()
        continue
      }
      const dependency = frame.deps[frame.index]
      frame.index += 1
      const seen = state.get(dependency)
      if (seen === 'open') {
        const start = path.indexOf(dependency)
        throw new CycleError([...path.slice(start), dependency])
      }
      if (seen === undefined) {
        state.set(dependency, 'open')
        path.push(dependency)
        frames.push({ name: dependency, deps: orderedDeps(graph, dependency), index: 0 })
      }
    }
  }
}

/** A task's dependencies in ascending name order. */
export function orderedDeps(graph, name) {
  return [...graph.tasks.get(name).deps].sort(compareNames)
}

/**
 * Visits every task after all of its dependencies, in an order that only
 * depends on the graph being acyclic. Returns the names in that order.
 */
function dependencyOrder(graph) {
  const order = []
  const done = new Set()
  const opened = new Set()

  for (const root of sortedNames(graph)) {
    if (done.has(root)) continue
    const frames = [{ name: root, deps: graph.tasks.get(root).deps, index: 0 }]
    opened.add(root)
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.index === frame.deps.length) {
        frames.pop()
        done.add(frame.name)
        order.push(frame.name)
        continue
      }
      const dependency = frame.deps[frame.index]
      frame.index += 1
      if (done.has(dependency) || opened.has(dependency)) continue
      opened.add(dependency)
      frames.push({ name: dependency, deps: graph.tasks.get(dependency).deps, index: 0 })
    }
  }
  return order
}

/**
 * The schedule with unlimited workers: for every task its `start`, `finish`
 * and `depth`, plus the makespan `total`.
 */
export function analyse(graph) {
  const info = new Map()
  let total = 0

  for (const name of dependencyOrder(graph)) {
    const task = graph.tasks.get(name)
    let start = 0
    let depth = 0
    for (const dependency of task.deps) {
      const parent = info.get(dependency)
      if (parent.finish > start) start = parent.finish
      if (parent.depth + 1 > depth) depth = parent.depth + 1
    }
    const finish = start + task.cost
    info.set(name, { name, start, finish, depth })
    if (finish > total) total = finish
  }

  return { info, total }
}

/**
 * Each task's priority: the cost of the longest chain that begins at it,
 * counting its own cost and the costs down to a task nothing depends on.
 */
export function priorities(graph) {
  const priority = new Map()
  const order = dependencyOrder(graph)

  // A dependency comes before its dependents, so walking backwards settles
  // every dependent before the task it depends on.
  for (let i = order.length - 1; i >= 0; i -= 1) {
    const name = order[i]
    if (!priority.has(name)) priority.set(name, graph.tasks.get(name).cost)
    const value = priority.get(name)
    for (const dependency of graph.tasks.get(name).deps) {
      const cost = graph.tasks.get(dependency).cost
      const candidate = cost + value
      const known = priority.get(dependency)
      if (known === undefined || candidate > known) priority.set(dependency, candidate)
    }
  }

  for (const name of graph.tasks.keys()) {
    if (!priority.has(name)) priority.set(name, graph.tasks.get(name).cost)
  }
  return priority
}
