const edges = []
for (const raw of text.split('\n')) {
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  if (w[0] === 'task') tasks.set(w[1], { name: w[1], cost: Number(w[2]), deps: [] })
  else edges.push(w.slice(1))
}
for (const e of edges) {
  const t = tasks.get(e[0])
  for (const d of e.slice(1)) if (!t.deps.includes(d)) t.deps.push(d)
}
const names = [...tasks.keys()].sort()
// priority by brute force longest chain downward
const dependents = new Map(names.map((n) => [n, []]))
for (const t of tasks.values()) for (const d of t.deps) dependents.get(d).push(t.name)
const prio = new Map()
const chain = (n) => {
  if (prio.has(n)) return prio.get(n)
  let below = 0
  for (const c of dependents.get(n)) below = Math.max(below, chain(c))
  const v = tasks.get(n).cost + below
  prio.set(n, v)
  return v
}
names.forEach(chain)

const runs = names.length >= 0 ? Array.from({ length: workers }, () => []) : []
const free = Array.from({ length: workers }, () => 0)
const finish = new Map()
const left = new Set(names)
let time = 0
let makespan = 0
while (left.size > 0) {
  for (;;) {
    const worker = free.findIndex((f) => f <= time)
    if (worker === -1) break
    const ready = [...left].filter((n) => tasks.get(n).deps.every((d) => finish.has(d) && finish.get(d) <= time))
    if (ready.length === 0) break
    ready.sort((a, b) => (prio.get(b) - prio.get(a)) || (a < b ? -1 : a > b ? 1 : 0))
    const pick = ready[0]
    const end = time + tasks.get(pick).cost
    runs[worker].push(`${pick}@${time}-${end}`)
    free[worker] = end
    finish.set(pick, end)
    left.delete(pick)
    makespan = Math.max(makespan, end)
  }
  const next = free.filter((f) => f > time).sort((a, b) => a - b)[0]
  if (next === undefined) break
  time = next
}
let out = ''
runs.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
out += `makespan ${makespan}\n`
